function grove(host){const frame=new THREE.Group();frame.position.fromArray(spec.grove.position);frame.quaternion.copy(FACE.bottom);frame.name='Original Matrix real HY2.0-4P receiver';host.body.add(frame);const white=materials.plastic(0xd5ccb2),walls=[],contacts=[],tails=[];for(const x of[-4.85,4.85])walls.push(box(frame,[.5,4.6,5.8],[x,0,-2.9],white,'Grove side keyed wall'));for(const y of[-2.05,2.05])walls.push(box(frame,[9.2,.5,5.8],[0,y,-2.9],white,'Grove top/bottom wall'));const stop=box(frame,[9.2,3.6,.45],[0,0,-5.575],white,'Grove real deep stop');for(let i=0;i<4;i++){const x=3-i*2;contacts.push(box(frame,[.36,.36,4.7],[x,-.35,-3.0],metal(),'Independent Grove metal contact'));tails.push(box(host.body,[.36,1.5,2],[x,-6.8,-2.1],metal(),'Grove retained right-angle solder tail'));}for(const x of[-3.9,3.9])walls.push(box(frame,[.65,.8,1.2],[x,1.55,-.6],white,'Grove real locking guide'));const port=host.add(new Port({id:'grove',label:'HY2.0-4P G26/G32',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10.2,1,4.6],pinGrid:{cols:4,rows:1,pitch:2,center:[0,-.35],order:col=>col+1},pins:spec.grove.pins.map((name,i)=>({n:i+1,name})),meta:{role:'visual-connector',face:'bottom',scope:'Real4contact appearance and hierarchical attachment;no I2C/UART/power/firmware behavior'}}));return{frame,walls,stop,contacts,tails,port};}
