 const capGroup=new THREE.Group(),lens=plate(capGroup,20.25,20.25,.36,1,[0,0,-.18],new THREE.MeshPhysicalMaterial({color:0x45494a,roughness:.3,transparent:true,opacity:.48,depthWrite:false,clearcoat:1}),'Actual dark acrylic matrix pressure window'),button=host.add(new Button({id:'button',label:'Matrix front programmable key',mesh:capGroup,position:spec.main.position,travel:spec.main.travelMm,longPressMs:0,meta:{role:'visual-control',gpio:39,scope:'Input intent only;real lens press/actuator relationship and travel inferred;fixed25LED board does not move'}}));const plunger=cylinder(button.cap,.45,3.0,[8.9,1.75,-1.72],materials.plastic(0x78827a),'Real inferred peripheral lens pressure stem avoiding25LED optical paths'),switchBase=ring(host.body,1.05,.61,.8,[8.9,1.75,2.2],metal(),'Main key real hollow fixed switch housing'),switchReturn=cylinder(host.body,.61,.15,[8.9,1.75,2.15],materials.plastic(0x555e54),'Main key real deep return/contact floor');
 const reset=host.add(new NativeReset(native.parts.rear)),resetFrame=new THREE.Group();resetFrame.name='Original Matrix inferred reset receiver frame';resetFrame.position.set(-9.8,4.5,-2.7);resetFrame.quaternion.copy(FACE.right);host.body.add(resetFrame);
 const resetBase=plate(resetFrame,3.3,1.8,1.2,.12,[0,0,0],metal(),'Inferred reset fixed receiver with real positive-clearance bore',[{w:2.6,h:1}]),resetStop=box(host.body,[.15,3.3,1.8],[-8.525,4.5,-2.7],metal(),'Inferred reset fixed receiver deep stop'),resetSupports=[-1,1].map(s=>box(host.body,[1.2,.3,.4],[-9.2,4.5+s*1.5,-1.6],metal(),'Inferred reset receiver support joined to main PCB')),resetFollower=box(host.body,[1.11,2.3,.7],[-9.555,4.5,-2.7],materials.plastic(0x4d5951),'Inferred reset native-inner-wall follower retained inside receiver');reset.bindFollower(resetFollower);
